@app.post("/heartbeat", dependencies=[Depends(require_token)])
def post_heartbeat(body: HeartbeatBody, conn=Depends(get_conn)):
    kwargs: dict = {}
    if body.ttl is not None:
        kwargs["ttl"] = body.ttl
    ok = leases_mod.heartbeat(conn, body.lease_id, body.agent_id, **kwargs)
    return {"ok": ok}

